using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Diagnostics;
using System.Windows;
using Microsoft.Win32;
namespace FlowShift {
public static class DesktopTests {
 public static int Run(string dir){Directory.CreateDirectory(dir);var log=new List<string>();Action<bool,string> check=(valid,name)=>{if(!valid)throw new Exception("FAIL "+name);log.Add("PASS "+name);};try{
  var defaults=new Preferences();check(defaults.MouseButton==2&&defaults.HoldMs==650&&defaults.Modifier=="无","default unmodified right-button hold");
  Preferences.Home=Path.Combine(dir,"profile");Directory.CreateDirectory(Preferences.Home);File.WriteAllText(Path.Combine(Preferences.Home,"settings.json"),"{\"Modifier\":\"Ctrl\",\"MouseButton\":1,\"HoldMs\":0}");var migrated=Preferences.Load();check(migrated.MouseButton==2&&migrated.HoldMs==650&&migrated.Modifier=="无","migrate old default gesture");
  File.WriteAllText(Path.Combine(Preferences.Home,"settings.json"),"{\"Modifier\":\"Shift\",\"MouseButton\":4,\"HoldMs\":900}");migrated=Preferences.Load();check(migrated.MouseButton==4&&migrated.HoldMs==900&&migrated.Modifier=="Shift","preserve customized old gesture");
  migrated.DockEdge="Left";migrated.DockAlong=.25;migrated.CompassKey=0x51;migrated.CompassModifiers=6;migrated.Save();var reloaded=Preferences.Load();check(reloaded.DockEdge=="Left"&&reloaded.DockAlong==.25&&reloaded.CompassKey==0x51&&reloaded.CompassModifiers==6,"persist edge and keyboard shortcut");
  foreach(var work in new[]{new Rect(0,0,1920,1040),new Rect(-1920,-400,1920,1080),new Rect(1920,0,1280,680)})foreach(string edge in new[]{"Left","Right","Top","Bottom"}){foreach(double along in new[]{0.0,.5,1.0}){Rect peek=EdgeLayout.Peek(edge,work,along);check(work.Contains(peek),"peek contained "+edge+" "+work.Left+" "+along);Rect panel=EdgeLayout.Panel(edge,work,along,500,640);check(work.Contains(panel),"panel contained "+edge+" "+work.Left+" "+along);}}
  var area=new Rect(0,0,1920,1040);check(EdgeLayout.Detect(new Rect(3,200,226,106),area,24)=="Left","snap left");check(EdgeLayout.Detect(new Rect(1700,200,226,106),area,24)=="Right","snap right");check(EdgeLayout.Detect(new Rect(400,3,226,106),area,24)=="Top","snap top");check(EdgeLayout.Detect(new Rect(400,940,226,106),area,24)=="Bottom","snap bottom");check(EdgeLayout.Detect(new Rect(400,300,226,106),area,24)=="","no snap in center");
  check(!Hook.Reached(650,649,100,100,70)&&Hook.Reached(650,650,0,0,70),"hold threshold does not turn a short click into a trigger");check(!Hook.Reached(0,1000,20,20,70)&&Hook.Reached(0,1,80,0,70),"drag distance threshold");
  check(HotkeyText.Valid(3,0x20)&&HotkeyText.Valid(0,0x71)&&!HotkeyText.Valid(0,0x41)&&!HotkeyText.Valid(4,0x41)&&!HotkeyText.Valid(3,0),"global shortcut constraints");
  using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("FlowShift.AppIcon"))check(stream!=null&&stream.Length>100,"embedded tray icon resource");using(var icon=AppVisual.LoadIcon())using(var bitmap=icon.ToBitmap()){int blue=0;for(int y=0;y<bitmap.Height;y++)for(int x=0;x<bitmap.Width;x++){var c=bitmap.GetPixel(x,y);if(c.A>0&&c.B>140&&c.R<150)blue++;}check(blue>8,"tray icon contains visible blue artwork");}
  var window=new MainWindow(true);window.Pref.EdgeAutoHide=true;var dock=new FloatingDock(window,true);dock.Show();foreach(string side in new[]{"Left","Right","Top","Bottom"}){dock.HideAtEdge(side);check(dock.IsEdgeHidden&&Math.Min(dock.Width,dock.Height)==18,"live window edge handle "+side);dock.Expand();check(!dock.IsEdgeHidden&&dock.Width>200&&dock.Height>300,"live window expand "+side);dock.Collapse();check(dock.IsEdgeHidden,"live window collapse "+side);}dock.Expand();dock.Close();window.Close();
  string exe=Assembly.GetExecutingAssembly().Location;check(DesktopIntegration.Command(exe,"pdf").EndsWith("--shell --target pdf \"%1\""),"quoted Explorer command");
  string testKey=@"Software\FlowShift\Testing\"+Guid.NewGuid().ToString("N");try{using(var classes=Registry.CurrentUser.CreateSubKey(testKey)){DesktopIntegration.RegisterIn(classes,exe);using(var key=classes.OpenSubKey(@"*\shell\FlowShift.Convert\shell"))check(key!=null&&key.SubKeyCount==10,"cascading file menu commands");using(var key=classes.OpenSubKey(@"Directory\shell\FlowShift.Convert\shell\04_pdf\command"))check(key!=null&&((string)key.GetValue("")).Contains("--target pdf"),"folder menu target command");DesktopIntegration.UnregisterIn(classes,exe+".other");using(var key=classes.OpenSubKey(@"*\shell\FlowShift.Convert"))check(key!=null,"unregister keeps another executable owner");DesktopIntegration.UnregisterIn(classes,exe);using(var key=classes.OpenSubKey(@"*\shell\FlowShift.Convert"))check(key==null,"unregister removes owned menu");}}
   finally{if(testKey.StartsWith(@"Software\FlowShift\Testing\",StringComparison.Ordinal))try{Registry.CurrentUser.DeleteSubKeyTree(testKey,false);}catch{}}
  string sample=Path.Combine(dir,"file with spaces.txt");File.WriteAllText(sample,"sample");var request=InstanceInbox.Parse(new[]{"--shell","--target","pdf",sample});check(request.Files.Length==1&&request.Target=="pdf"&&request.Kind=="files","parse shell request");Directory.CreateDirectory(InstanceInbox.Root);var process=Process.GetCurrentProcess();File.WriteAllText(Path.Combine(InstanceInbox.Root,"instance"),process.Id+"|"+process.StartTime.ToUniversalTime().Ticks);int pending=Directory.GetFiles(InstanceInbox.Root,"*.json").Length;check(InstanceInbox.TrySend(request)&&Directory.GetFiles(InstanceInbox.Root,"*.json").Length==pending+1,"send request to running instance inbox");File.WriteAllText(Path.Combine(InstanceInbox.Root,"instance"),process.Id+"|1");check(!InstanceInbox.TrySend(request),"reject stale instance identity");
  File.WriteAllLines(Path.Combine(dir,"desktop-tests.txt"),log);return 0;
 }catch(Exception ex){log.Add(ex.ToString());File.WriteAllLines(Path.Combine(dir,"desktop-tests.txt"),log);return 1;}}
}
}
